<?php require_once __DIR__ . '/auth.php'; require_login('admin');$subjects=many('SELECT * FROM subjects ORDER BY name');$question=isset($_GET['id'])?one('SELECT * FROM questions WHERE id=?','i',[(int)$_GET['id']]):null;$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$data=[(int)$_POST['subject_id'],(int)$_POST['topic_id'],$_POST['difficulty'],trim($_POST['question']),trim($_POST['option_a']),trim($_POST['option_b']),trim($_POST['option_c']),trim($_POST['option_d']),$_POST['correct_answer'],(int)$_POST['marks']];if(!$data[3]||!$data[4]||!$data[5]||!$data[6]||!$data[7])$error='Complete the question and all four options.';else{if(!empty($_POST['id'])){query('UPDATE questions SET subject_id=?,topic_id=?,difficulty=?,question=?,option_a=?,option_b=?,option_c=?,option_d=?,correct_answer=?,marks=? WHERE id=?','iissssssiii',array_merge($data,[(int)$_POST['id']]));}else{query('INSERT INTO questions (subject_id,topic_id,difficulty,question,option_a,option_b,option_c,option_d,correct_answer,marks) VALUES (?,?,?,?,?,?,?,?,?,?)','iisssssssi',$data);}redirect('questions.php');}}$pageTitle=$question?'Edit question':'Add question';include 'includes/header.php';?><div class="page-head"><div><div class="eyebrow">Question studio</div><h1><?=e($pageTitle)?>.</h1><p>Make each prompt clear, fair, and useful.</p></div></div><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><section class="panel" style="max-width:850px"><form method="post" class="form-stack"><input type="hidden" name="id" value="<?=$question['id']??''?>"><div class="form-grid"><label>Subject<select name="subject_id" required><?php foreach($subjects as $subject):?><option value="<?=$subject['id']?>" <?=($question['subject_id']??'')==$subject['id']?'selected':''?>><?=e($subject['name'])?></option><?php endforeach;?></select></label><label>Topic ID<input type="number" name="topic_id" value="<?=$question['topic_id']??1?>" min="1" required></label></div><div class="form-grid"><label>Difficulty<select name="difficulty"><option>Easy</option><option <?=($question['difficulty']??'')==='Medium'?'selected':''?>>Medium</option><option <?=($question['difficulty']??'')==='Hard'?'selected':''?>>Hard</option></select></label><label>Marks<input type="number" name="marks" value="<?=$question['marks']??10?>" min="1"></label></div><label>Question<textarea name="question" rows="4" required><?=e($question['question']??'')?></textarea></label><div class="form-grid"><label>Option A<input name="option_a" required value="<?=e($question['option_a']??'')?>"></label><label>Option B<input name="option_b" required value="<?=e($question['option_b']??'')?>"></label><label>Option C<input name="option_c" required value="<?=e($question['option_c']??'')?>"></label><label>Option D<input name="option_d" required value="<?=e($question['option_d']??'')?>"></label></div><label>Correct answer<select name="correct_answer"><option>A</option><option <?=($question['correct_answer']??'')==='B'?'selected':''?>>B</option><option <?=($question['correct_answer']??'')==='C'?'selected':''?>>C</option><option <?=($question['correct_answer']??'')==='D'?'selected':''?>>D</option></select></label><button class="button button-primary">Save question ↗</button></form></section><?php include 'includes/footer.php';?>